export function calculateGaugeFeePercentage(gauge) {
  if (gauge.poolType === "V2") {
    return "0.30";
  } else if (gauge.tickSpacing) {
    const tickSpacing = parseInt(gauge.tickSpacing);
    const TICK_SPACING_TO_FEE = {
      1: 100,
      // 0.01%
      50: 500,
      // 0.05%
      100: 500,
      // 0.05%
      200: 3e3,
      // 0.30%
      2e3: 1e4
      // 1.00%
    };
    const feeBasisPoints = TICK_SPACING_TO_FEE[tickSpacing] || 3e3;
    return (feeBasisPoints / 1e4).toFixed(2);
  }
  return "0.30";
}
async function fetchGaugeData(subgraphUrl) {
  try {
    const response = await fetch(subgraphUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: ALL_GAUGES_QUERY })
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
    const data = await response.json();
    if (data.errors) {
      console.error("GraphQL Errors:", data.errors.map((e) => e.message));
      throw new Error(`GraphQL errors: ${JSON.stringify(data.errors)}`);
    }
    return data.data;
  } catch (error) {
    console.error("Gauge query failed:", error);
    throw error;
  }
}
export function useGaugesData() {
  const { chainId } = useAccount();
  return useQuery({
    queryKey: ["gauges", chainId],
    queryFn: async () => {
      const subgraphs = chainId ? getAbstractSubgraphs(chainId) : null;
      if (!subgraphs?.gauges) {
        throw new Error("Gauge subgraph not available for this chain");
      }
      try {
        const data = await fetchGaugeData(subgraphs.gauges);
        const gauges = data?.gauges || [];
        const poolMappings = data?.poolGaugeMappings || [];
        return { gauges, poolMappings };
      } catch (error) {
        console.error("Gauge data query failed:", error);
        return { gauges: [], poolMappings: [] };
      }
    },
    enabled: Boolean(chainId),
    staleTime: 3e4,
    refetchInterval: 6e4
  });
}
export function useUserGaugeData() {
  const { address, chainId } = useAccount();
  return useQuery({
    queryKey: ["userGauges", address, chainId],
    queryFn: async () => {
      const subgraphs = chainId ? getAbstractSubgraphs(chainId) : null;
      if (!subgraphs?.gauges || !address) {
        throw new Error("Missing subgraph URL or user address");
      }
      const response = await fetch(subgraphs.gauges, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          query: GAUGES_QUERY,
          variables: { user: address.toLowerCase() }
        })
      });
      if (!response.ok) {
        throw new Error(`Failed to fetch user gauge data: ${response.statusText}`);
      }
      const data = await response.json();
      if (data.errors) {
        console.error("User gauge GraphQL errors:", data.errors);
        throw new Error(`GraphQL errors: ${JSON.stringify(data.errors)}`);
      }
      return {
        gauges: data.data?.gauges || [],
        stakes: data.data?.gaugeStakes || [],
        claims: data.data?.rewardClaims || []
      };
    },
    enabled: Boolean(chainId && address),
    staleTime: 3e4,
    refetchInterval: 6e4
  });
}
export function useGaugeForPool(poolAddress) {
  const { data: gaugeData, isLoading } = useGaugesData();
  const gauge = gaugeData?.poolMappings?.find((mapping) => {
    const mappingPoolAddress = mapping.pool.toLowerCase();
    const targetPoolAddress = poolAddress?.toLowerCase();
    return mappingPoolAddress === targetPoolAddress;
  });
  return {
    gauge: gauge ? { id: gauge.gauge } : null,
    poolMapping: gauge,
    isLoading,
    hasGauge: Boolean(gauge)
  };
}
export function useAvailableGauges(enabled = true, chainId = UniverseChainId.Mainnet) {
  return useQuery({
    queryKey: ["available-gauges-with-pools", chainId],
    queryFn: async () => {
      const subgraphs = getAbstractSubgraphs(chainId);
      const gaugeData = await fetchDataFromSubgraph(
        GET_AVAILABLE_GAUGES_QUERY,
        subgraphs.gauges
      );
      if (!gaugeData?.gauges || gaugeData.gauges.length === 0) {
        return [];
      }
      const allPoolIds = gaugeData.gauges.map((g) => g.pool.toLowerCase());
      const v2Data = await fetchDataFromSubgraph(
        GET_V2_POOLS_BY_IDS,
        subgraphs.v2,
        { ids: allPoolIds }
      );
      const v2Pools = v2Data?.pairs || [];
      const v3Data = await fetchDataFromSubgraph(
        GET_V3_POOLS_BY_IDS,
        subgraphs.v3,
        { ids: allPoolIds }
      );
      const v3Pools = v3Data?.pools || [];
      const v2PoolMap = /* @__PURE__ */ new Map();
      const v3PoolMap = /* @__PURE__ */ new Map();
      v2Pools.forEach((pool) => v2PoolMap.set(pool.id.toLowerCase(), pool));
      v3Pools.forEach((pool) => v3PoolMap.set(pool.id.toLowerCase(), {
        ...pool,
        reserveUSD: pool.totalValueLockedUSD
      }));
      const enhancedGauges = gaugeData.gauges.map((gauge) => {
        const poolId = gauge.pool.toLowerCase();
        const v2PoolData = v2PoolMap.get(poolId);
        const v3PoolData = v3PoolMap.get(poolId);
        let correctedPoolType = gauge.poolType;
        let poolData = null;
        if (v2PoolData) {
          correctedPoolType = "V2";
          poolData = v2PoolData;
        } else if (v3PoolData) {
          correctedPoolType = "V3";
          poolData = v3PoolData;
        }
        if (poolData) {
          return {
            ...gauge,
            poolType: correctedPoolType,
            // Use corrected poolType based on actual subgraph data
            token0: poolData.token0,
            token1: poolData.token1,
            tickSpacing: poolData.tickSpacing,
            // Include tick spacing for V3 pools
            reserveUSD: poolData.reserveUSD,
            volumeUSD: poolData.volumeUSD,
            votes: gauge.totalWeight,
            stable: poolData.stable
            // Include stable flag for V2 pools
          };
        }
        return gauge;
      });
      return enhancedGauges;
    },
    enabled,
    staleTime: 3e4,
    refetchInterval: 6e4
  });
}
export function calculatePoolIncentives(gaugePool) {
  let totalIncentives = 0;
  let totalEmissions = 0;
  if (gaugePool.emissions && gaugePool.emissions !== "0") {
    try {
      totalEmissions = parseFloat((BigInt(gaugePool.emissions) / BigInt(10 ** 18)).toString());
    } catch (error) {
      console.warn("Failed to parse emissions:", gaugePool.emissions, error);
    }
  }
  if (gaugePool.rewardDistributions) {
    gaugePool.rewardDistributions.forEach((distribution) => {
      if (distribution.amount && distribution.amount !== "0") {
        try {
          const amount = parseFloat((BigInt(distribution.amount) / BigInt(10 ** 18)).toString());
          totalIncentives += amount;
        } catch (error) {
          console.warn("Failed to parse reward distribution:", distribution.amount, error);
        }
      }
    });
  }
  const totalRewards = totalIncentives + totalEmissions;
  const incentivesFormatted = totalRewards > 0 ? `${totalRewards.toLocaleString(void 0, { maximumFractionDigits: 0 })} ABX` : "-";
  return {
    totalIncentives,
    totalEmissions,
    totalRewards,
    incentivesFormatted
  };
}
export function calculatePoolTradingFeesLastEpoch(gaugePool) {
  const currentTime = Date.now() / 1e3;
  const currentEpoch = Math.floor(currentTime / (7 * 24 * 60 * 60));
  const lastEpoch = currentEpoch - 1;
  let totalTradingFees = 0;
  const feeTokenMap = /* @__PURE__ */ new Map();
  if (gaugePool.rewardDistributions) {
    gaugePool.rewardDistributions.forEach((distribution) => {
      if (distribution.amount && distribution.amount !== "0") {
        const distributionEpoch = parseInt(distribution.epoch || "0");
        if (distributionEpoch === lastEpoch) {
          try {
            const amount = parseFloat((BigInt(distribution.amount) / BigInt(10 ** 18)).toString());
            let tokenSymbol = "UNKNOWN";
            let isTradingFee = false;
            if (distribution.token === "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d") {
              tokenSymbol = "WETH";
              isTradingFee = true;
            } else if (distribution.token === "0x698f98ab816670692fa9dd8e1486ea0fd253e996") {
              tokenSymbol = "USDC";
              isTradingFee = true;
            } else if (distribution.token === "0x0000000000000000000000000000000000000000") {
              tokenSymbol = "ETH";
              isTradingFee = true;
            }
            if (isTradingFee) {
              totalTradingFees += amount;
              feeTokenMap.set(tokenSymbol, (feeTokenMap.get(tokenSymbol) || 0) + amount);
            }
          } catch (error) {
            console.warn("Failed to parse trading fee distribution:", distribution.amount, error);
          }
        }
      }
    });
  }
  const feeBreakdown = Array.from(feeTokenMap.entries()).map(([symbol, amount]) => ({
    symbol,
    amount: amount < 1e3 ? amount.toFixed(2) : amount < 1e6 ? (amount / 1e3).toFixed(2) + "K" : (amount / 1e6).toFixed(2) + "M"
  }));
  const formattedTotal = totalTradingFees > 0 ? totalTradingFees < 1e3 ? totalTradingFees.toFixed(2) : totalTradingFees < 1e6 ? (totalTradingFees / 1e3).toFixed(2) + "K" : (totalTradingFees / 1e6).toFixed(2) + "M" : "-";
  return {
    totalTradingFees,
    feeBreakdown,
    formattedTotal
  };
}
const SECONDS_PER_WEEK = 7 * 24 * 60 * 60;
const WEEKS_PER_YEAR = 52;
export function calculatePoolLPAPR({
  rewardRatePerSecond,
  stakedTvlUSD,
  abxPriceUSD
}) {
  if (!rewardRatePerSecond || rewardRatePerSecond <= 0) {
    return 0;
  }
  if (!stakedTvlUSD || stakedTvlUSD <= 0) {
    return 0;
  }
  if (!abxPriceUSD || abxPriceUSD <= 0) {
    return 0;
  }
  const weeklyEmissionsABX = rewardRatePerSecond * SECONDS_PER_WEEK;
  const annualRewardsUSD = weeklyEmissionsABX * WEEKS_PER_YEAR * abxPriceUSD;
  const apr = annualRewardsUSD / stakedTvlUSD * 100;
  return Number.isFinite(apr) ? apr : 0;
}
