export function calculateEstimatedRewards(gaugePool, userVotePercentage, userTotalVotingPower, abxPrice = 1) {
  const { totalRewards } = calculatePoolIncentives(gaugePool);
  if (totalRewards === 0) {
    return {
      rewardsABX: 0,
      rewardsUSD: 0,
      formattedUSD: "$0.00"
    };
  }
  const userVoteWeight = userVotePercentage / 100 * userTotalVotingPower;
  const totalPoolWeight = gaugePool.totalWeight ? parseFloat(gaugePool.totalWeight) : 0;
  if (totalPoolWeight === 0) {
    return {
      rewardsABX: 0,
      rewardsUSD: 0,
      formattedUSD: "$0.00"
    };
  }
  const userShareOfPool = userVoteWeight / totalPoolWeight;
  const estimatedRewardsABX = userShareOfPool * totalRewards;
  const estimatedRewardsUSD = estimatedRewardsABX * abxPrice;
  return {
    rewardsABX: estimatedRewardsABX,
    rewardsUSD: estimatedRewardsUSD,
    formattedUSD: estimatedRewardsUSD > 0 ? `~$${estimatedRewardsUSD.toFixed(2)}` : "$0.00"
  };
}
